// Marks the log chain in which a player was initialized (new connection or seamless travel).
// Squads autogenerated for that player are created later in the same chain.
export default {
  regex: /^\[([\d.:-]+)]\[([ \d]*)]LogGameMode: Initialized player (.+) with \d+$/,
  onMatch: (args, logParser) => {
    if (!logParser.eventStore.initializedPlayers) logParser.eventStore.initializedPlayers = {};
    logParser.eventStore.initializedPlayers[+args[2]] = args[3];
  }
};
